catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {


   //Type appropriate comment here, and begin script below
   console.log("Client Script: Starting execution...")
   var action_type =  newValue;

   console.log("action_type", action_type);

   if(action_type == 'create' || action_type == 'update'){

			g_form.clearValue('book_title');
        g_form.clearValue('author_s_name');
        g_form.clearValue('genre');
        g_form.clearValue('total_copies');
        g_form.clearValue('available_copies');
		 g_form.clearValue('select_book');
		 g_form.setMandatory('book_title', true);
        g_form.setMandatory('author_s_name', true);
        g_form.setMandatory('genre', true);
		g_form.setMandatory('select_book', action_type == 'update');
        g_form.setMandatory('total_copies', true);
        g_form.setMandatory('available_copies', true);
		g_form.setVisible('book_title', true);
        g_form.setVisible('author_s_name', true);
        g_form.setVisible('genre', true);
        g_form.setVisible('total_copies', true);
        g_form.setVisible('available_copies', true);
        g_form.setVisible('select_book', action_type == 'update');
   }else if(action_type == 'delete'){
			g_form.clearValue('book_title');
        g_form.clearValue('author_s_name');
        g_form.clearValue('genre');
        g_form.clearValue('total_copies');
        g_form.clearValue('available_copies');
		 g_form.clearValue('select_book');

			 g_form.setMandatory('book_title', false);
        g_form.setMandatory('author_s_name', false);
        g_form.setMandatory('genre', false);
		g_form.setMandatory('select_book', true);
        g_form.setMandatory('total_copies', false);
        g_form.setMandatory('available_copies',false);

		g_form.setVisible('book_title', false);
        g_form.setVisible('author_s_name', false);
        g_form.setVisible('genre', false);
        g_form.setVisible('total_copies', false);
        g_form.setVisible('available_copies', false);
        g_form.setVisible('select_book', true);
   }

}
